"""Private full-main Stiger1999 characterization extraction; source and Site read-only."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json
B=Path(__file__).resolve().parent; SID='stiger1999'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def ev(p,s):return {'source_id':SID,'pdf_page':p,'printed_page':789+p,'locator':s}
def q(v=None,u=None,lo=None,hi=None,approx=False,raw=None):
 d={'value':v,'unit':u}
 if lo is not None:d.update(lower_bound=lo,upper_bound=hi)
 if approx:d['approximate']=True
 if raw:d['raw_text']=raw
 return d
rows=[]
def row(k,s,prop,v,p,where,basis='reported',method=None,condition=None,caveat=None,scope='source_cohort'):
 d={'id':'char-'+k,'sample_id':s,'scope_type':scope,'property':prop,'basis':basis,'evidence':[ev(p,where)],'eligible_training':False}
 d['quantity' if isinstance(v,dict) else 'fact']=v
 if method:d['method']=method
 if condition:d['source_condition']=condition
 if caveat:d['caveat']=caveat
 rows.append(d)

# Substrate/measurement references are separate from silver-particle dimensions.
row('si-step-height','etched-si-reference','silicon_monatomic_step_height',q(1.3,'angstrom',raw='1.3 ± 0.4 Å'),2,'II.A and Figure 1',method='NC-AFM',caveat='The ±0.4 Å quantity has no declared statistical definition; this is substrate topography, not silver height.')
row('si-step-uncertainty','etched-si-reference','reported_step_height_uncertainty',q(.4,'angstrom'),2,'II.A and Figure 1 caption',method='NC-AFM',caveat='Reported ± quantity; SD/SEM not specified.')
