equations=[
 {'id':'equation-1','number':1,'expression':'I(t) = z N F π (2 D_Ag+ C_Ag+)^(3/2) M_Ag^(1/2) t^(1/2) / ρ_Ag^(1/2)','scope':'Instantaneous nucleation model for the rising transient, cited to Hills et al. (42).','evidence':[ev(4,'Equation 1')],'limitations':['I is called current in text but plotted as current density. N is areal density. Preserve source notation.']},
 {'id':'equation-2','number':2,'expression':'I(t) = z N_∞ A π (2 D_Ag+ C*_Ag+)^(3/2) M_Ag^(1/2) t^(3/2) / (3 ρ_Ag^(1/2))','scope':'Progressive nucleation model, printed form preserved.','evidence':[ev(5,'Equation 2')],'limitations':['The printed expression contains A, not defined numerically in the supplied main, and does not visibly contain the F factor present in Equation 1. No missing factor is silently inserted.','N∞ is the nucleation-site density at infinite time; not the directly measured AFM density at one pulse.','Source note 43 lists C, D and ρ but does not supply a full independent reproducibility specification.']},
 {'id':'equation-3','number':3,'expression':'r(Q) = [(3/2) M_Ag / (z π F ρ_Ag N)]^(1/3) Q_Ag^(1/3)','scope':'Hemispherical geometry/charge relation strictly for instantaneous nucleation; used as a consistency comparison.','evidence':[ev(9,'Equation 3'),ev(8,'Figure 9 caption')],'limitations':['r is particle height under the hemispherical model, not a measured spherical diameter.','Source p9 calls the displayed predictions Figure 8, while the curves occur in Figure 9.','Q units differ between printed Figure 5 prose/captions and Figures 7/9 axes.']},
 {'id':'miscut-relation','number':None,'expression':'(1.3 Å per step)(40 steps)/(42,400 Å) × 100% ≈ 0.1%','scope':'Unnumbered substrate miscut percent-slope calculation.','evidence':[ev(2,'II.A')],'limitations':['No conversion to degrees is performed.']},
]
