manifest=json.loads((B/'source-render-manifest.json').read_text(encoding='utf-8'));source_sha=sha(Path(manifest['source']));assert source_sha==manifest['sha256']
payload={'schema_version':'private-characterization-extraction/1.0','generated_at':datetime.now(timezone.utc).isoformat(),'source':{'source_id':SID,'doi':'10.1021/la980800b','title':'Investigations of Electrochemical Silver Nanocrystal Growth on Hydrogen-Terminated Silicon(100)','authors':['R. M. Stiger','S. Gorer','B. Craft','R. M. Penner'],'journal':'Langmuir','year':1999,'volume':15,'pages':'790–798','published_online':'1998-12-09','path':manifest['source'],'sha256':source_sha,'review_scope':'All nine supplied main pages read as text and visually. SI not verified by this bounded characterization extraction.'},'review_status':{'private_extraction':'completed draft','canonical_integration':'not performed','reader_render_audit':'not performed','publication':'not performed','eligible_training':False},'page_review':[{'pdf_page':n,'printed_page':789+n,'text_read':True,'visually_reviewed':True,'text_sha256':sha(B/f'page-{n}.txt'),'render_sha256':sha(B/f'page-{n}.png')} for n in range(1,10)],'measurement_methods':methods,'measurement_rows':rows,'figures':figures,'tables':[{'id':'table-1','pdf_page':7,'rows':TABLE1,'scope':'Measured SAED spacings versus reference ICDD spacings/intensities; distinct evidence classes.'}],'schemes':[scheme],'equations':equations,'conflicts_and_limitations':[{'id':k,'text':t,'evidence':[ev(p,'Source text/figure conflict; see linked characterization row locators') for p in pages]} for k,t,pages in conflicts],'sample_scope_policy':'Source contexts and plotted/panel cohorts are not exact physical batch identities. No raw data digitization, hidden fifth histogram, 15 reconstructed per-point recipes, exact atom coordinates or measured interface model is supplied.','not_reported':['Raman or optical absorption/PL spectra','Quantitative catalytic/device performance','XRD pattern','Refined lattice parameters or measured atom coordinates/CIF','Raw AFM particle lists or full time-current arrays','Reference conversion calibration','Measured band-edge positions','Exact Fig6 deposition duration','Faradaic efficiency or exact Ag yield','Individual sample-to-day/calendar mapping','Valid density error-bar statistic in Figure 8'],'counts':{'pages':9,'measurement_rows':len(rows),'figures':9,'tables':1,'numbered_schemes':1,'numbered_equations':3,'unnumbered_calculation_contexts':1,'histogram_panels':4,'saed_table_rows':4,'conflicts':len(conflicts)}}
checks=[]
def ck(n,v):checks.append({'name':n,'passed':bool(v)});assert v,n
ck('nine text and visual pages',len(payload['page_review'])==9)
ck('unique typed row IDs',len({r['id'] for r in rows})==len(rows))
ck('all rows have source locators',all(r['evidence'] and 1<=r['evidence'][0]['pdf_page']<=9 for r in rows))
ck('nine figures and one table',len(figures)==9 and len(TABLE1)==4)
ck('four actual histograms',len(F7)==4 and [r['mean_height_nm'] for r in F7]==[2.2,7.5,13.5,17.1])
ck('source sigma labels', [r['height_sigma_nm'] for r in F7]==[2.4,4.3,5.3,6.1])
ck('unit conflict retained',all(p['charge_as_printed']['unit']=='mC/cm^2' for p in F5) and rows[[r['id'] for r in rows].index('char-f7-1-charge')]['quantity']['unit']=='uC/cm^2')
ck('reference and measured d spacings separated',TABLE1[0]['measured_d_angstrom']==2.37 and TABLE1[0]['reference_d_angstrom']==2.32)
ck('training gates disabled',all(not r['eligible_training'] for r in rows))
ck('source hash verified',source_sha==manifest['sha256'])
(B/'characterization-draft.json').write_text(json.dumps(payload,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
lines=['# Stiger et al. 1999 — characterization extraction','','All nine supplied main pages were read as text and visually. Private draft only; SI, canonical, reader and publication gates remain separate.','',f'Source SHA256: `{source_sha}`','',json.dumps(payload['counts'],indent=2),'','## Typed evidence','','| ID | Scope | Property | Value | Basis / page |','|---|---|---|---|---|']
for r in rows:lines.append('| '+ ' | '.join([r['id'],str(r['sample_id']),r['property'],json.dumps(r.get('quantity',r.get('fact')),ensure_ascii=False).replace('|','\\|'),r['basis']+' / '+str(r['evidence'][0]['pdf_page'])])+' |')
lines+=['','## Conflicts and limits','']+['- **'+k+'**: '+t for k,t,_ in conflicts]+['','## Original assets','']+['- '+f['id']+': '+f['title']+'. '+f['scope'] for f in figures]+['','One four-row SAED table, one six-panel band model scheme, three numbered equations and one unnumbered miscut calculation are retained. Figure 6 includes the actual SAED pattern; its ring-index diagram is separately identified.','']
(B/'characterization-draft.md').write_text('\n'.join(lines),encoding='utf-8')
val={'status':'passed','checks':checks,'counts':payload['counts'],'artifact_sha256':{n:sha(B/n) for n in ['characterization-draft.json','characterization-draft.md']},'scope':'Private source extraction consistency, not canonical/reader/publication promotion.'}
(B/'characterization-validation.json').write_text(json.dumps(val,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
